fn solve(n: i8, s: Vec<char>) -> i8 {
    if n == 0 {
        return 0;
    }

    let mut x = 0;
    let mut y = 0;
    let mut transitions = 0;
    let mut last_region = None; // None for border, Some(true) for A, Some(false) for B

    for &move_char in &s {
        match move_char {
            'U' => y += 1,
            'R' => x += 1,
            _ => continue, // In case of invalid character, though not expected
        }

        // Determine the current region
        let current_region = if x > y {
            Some(true) // Region A
        } else if y > x {
            Some(false) // Region B
        } else {
            None // Border
        };

        // Check for transitions
        if let Some(region) = current_region {
            if last_region.is_none() {
                // First move into a region, do not count as a transition
                last_region = Some(region);
            } else if last_region != Some(region) {
                // Transition occurred
                transitions += 1;
                last_region = Some(region);
            }
        } else {
            // On the border, we do not count transitions
            last_region = None;
        }
    }

    transitions
}